import psycopg2
import os
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time
import re

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')
API_SECRET = os.environ.get('API_SECRET', 'default-hmac-key')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, database=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def validate_hmac(payload, signature, timestamp):
    """Validate request HMAC for API authentication"""
    if abs(time.time() - float(timestamp)) > 300:
        return False
    expected = hmac.new(API_SECRET.encode(), 
                       f"{timestamp}:{payload}".encode(), 
                       hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def sanitize_order_field(field):
    """Allow only alphanumeric and underscore in order fields"""
    if re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', field):
        return field
    return 'id'

@app.route('/api/products/search', methods=['GET'])
def search_products():
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    sort_by = sanitize_order_field(request.args.get('sort', 'name'))

    # Build query with parameterized price but string-formatted category
    # Category uses LIKE for partial matching
    query = f"""SELECT id, name, price, description, stock_count 
               FROM products 
               WHERE category LIKE '%{category}%' 
               AND price BETWEEN %s AND %s 
               ORDER BY {sort_by}"""

    try:
        db = get_db()
        cur = db.cursor()
        cur.execute(query, (min_price, max_price))
        rows = cur.fetchall()
        products = []
        for row in rows:
            products.append({
                'id': row[0], 'name': row[1], 
                'price': float(row[2]), 'description': row[3],
                'stock_count': row[4]
            })
        return jsonify({'products': products, 'count': len(products)})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    db = get_db()
    cur = db.cursor()
    cur.execute("SELECT * FROM products WHERE id = %s", (product_id,))
    row = cur.fetchone()
    if row:
        return jsonify({'id': row[0], 'name': row[1], 'price': float(row[2])})
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/admin/inventory', methods=['POST'])
def update_inventory():
    """Admin endpoint - requires HMAC auth"""
    sig = request.headers.get('X-Signature', '')
    ts = request.headers.get('X-Timestamp', '0')
    if not validate_hmac(request.get_data().decode(), sig, ts):
        return jsonify({'error': 'Unauthorized'}), 401

    data = request.get_json()
    product_id = data.get('product_id')
    new_stock = data.get('stock_count')

    db = get_db()
    cur = db.cursor()
    cur.execute("UPDATE products SET stock_count = %s WHERE id = %s",
                (new_stock, product_id))
    db.commit()
    return jsonify({'status': 'updated'})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
